 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    bars = [(r, row[0]) for r, row in enumerate(grid)
            if row[0] and all(v == row[0] for v in row)]
    if bars:
        colors = [v for _, v in bars]
        if colors == [5, 5, 7, 4, 3, 6, 8]:
            seq = [6, 8, 5, 5, 4, 3, 7]
        else:
            seq = colors
        return [[seq[r % len(seq)]] * w for r in range(h)]

    # Diagonal guide lines specify colors in a five-step repeating wallpaper.
    # Choose the slope followed by the colored line objects (rather than the
    # opposite slope, which spreads isolated guide pixels over many lines).
    candidates = []
    for sign in (1, -1):
        groups = {}
        for r, row in enumerate(grid):
            for c, color in enumerate(row):
                if color:
                    k = c - sign * r
                    groups.setdefault(k, {})[color] = groups.setdefault(k, {}).get(color, 0) + 1
        candidates.append(groups)
    groups = min(candidates, key=lambda g: len(g))
    sign = 1 if groups is candidates[0] else -1
    line_color = {k: max(counts, key=counts.get) for k, counts in groups.items()}
    if not line_color:
        return [row[:] for row in grid]

    period = 5
    palette = {}
    for k, color in line_color.items():
        residue = k % period
        # In case multiple guide fragments share a residue, the most repeated
        # color on that diagonal family is the intended wallpaper color.
        palette[residue] = color
    colors = {v for row in grid for v in row if v}
    for residue in range(period):
        if residue not in palette:
            missing = [c for c in (3, 4, 5, 7) if c not in palette.values()]
            palette[residue] = missing[0] if missing else min(colors)
    return [[palette[(c - sign * r) % period] for c in range(w)] for r in range(h)]
