 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full-width colored rows encode samples of a vertical repeating word.
    bars = [(r, row[0]) for r, row in enumerate(grid)
            if row[0] and all(v == row[0] for v in row)]
    if bars:
        period = len(bars)
        word = {}
        for r, color in bars:
            word[r % period] = color
        # Every residue is represented by a guide bar in the demonstrations.
        return [[word[r % period] for _ in range(w)] for r in range(h)]

    # Diagonal guide tracks encode a one-dimensional periodic word. Select the
    # diagonal direction with fewer populated tracks, then use those tracks as
    # the residue/color samples of the repeated word.
    tracks_minus = {}
    tracks_plus = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                tracks_minus.setdefault(c-r, color)
                tracks_plus.setdefault(c+r, color)

    tracks = tracks_minus if len(tracks_minus) <= len(tracks_plus) else tracks_plus
    period = len(tracks)
    word = {}
    for offset, color in tracks.items():
        word[offset % period] = color
    fallback = sorted(set(v for row in grid for v in row if v))
    for k in range(period):
        word.setdefault(k, fallback[k % len(fallback)])

    use_minus = tracks is tracks_minus
    if use_minus:
        return [[word[(c-r) % period] for c in range(w)] for r in range(h)]
    return [[word[(r+c) % period] for c in range(w)] for r in range(h)]
