def transform(grid):
    h, w = len(grid), len(grid[0])

    # Solid horizontal guide rows encode samples of a vertical repeating word.
    bars = [(r, row[0]) for r, row in enumerate(grid)
            if row[0] and all(v == row[0] for v in row)]
    if bars:
        period, word = _smallest_period(bars)
        colors = sorted({v for _, v in bars})
        for k in range(period):
            word.setdefault(k, colors[k % len(colors)])
        return [[word[r % period] for _ in range(w)] for r in range(h)]

    # Diagonal guide lines are samples of a periodic stripe word. Try both
    # diagonal orientations and use the orientation with the shortest
    # conflict-free period; the guides determine the exact phase and colors.
    minus, plus = {}, {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                minus.setdefault(c-r, color)
                plus.setdefault(c+r, color)
    candidates = []
    for direction, tracks in (("minus", minus), ("plus", plus)):
        period, residues = _smallest_period(list(tracks.items()))
        candidates.append((period, direction, residues, tracks))
    period, direction, word, tracks = min(candidates, key=lambda item: item[0])
    colors = sorted({v for _, v in tracks.items()})
    for k in range(period):
        word.setdefault(k, colors[k % len(colors)])
    if direction == "minus":
        return [[word[(c-r) % period] for c in range(w)] for r in range(h)]
    return [[word[(c+r) % period] for c in range(w)] for r in range(h)]
